/* Teacher interaction layer: concise evidence, approval and deterministic demo state. */
(function(){
  const T=window.EDEVISER_TEACHER; if(!T || document.body.dataset.role!=='teacher') return;
  const page=(location.pathname.split('/').pop()||'teacher-dashboard.html').replace('.html','');
  const stateKey='edeviser-teacher-sarah-handoff';
  const getState=()=>{try{return localStorage.getItem(stateKey)||'pending'}catch(_){return 'pending'}};
  const setState=s=>{try{localStorage.setItem(stateKey,s)}catch(_){}};
  const close=()=>document.querySelector('.teacher-drawer-backdrop')?.remove();
  const drawer=(title,body)=>{close();const back=document.createElement('div');back.className='teacher-drawer-backdrop open';back.innerHTML=`<section class="teacher-drawer" role="dialog" aria-modal="true" aria-label="${title}"><div style="display:flex;gap:12px;align-items:flex-start;justify-content:space-between"><div><h2>${title}</h2><p style="margin:4px 0 0">${T.sarah.course} · ${T.sarah.code}</p></div><button class="text-sm font-bold text-slate-500" aria-label="Close">×</button></div>${body}</section>`;document.body.appendChild(back);back.addEventListener('click',e=>{if(e.target===back||e.target.closest('[aria-label="Close"]'))close()});document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',esc)}});back.querySelector('button').focus();};
  window.openSarahEvidence=()=>drawer('Why Sarah needs attention',`<h3>Current outcome</h3><div class="evidence"><div><b>${T.sarah.outcome}</b>${T.sarah.mastery}% · ${T.sarah.status}</div><div><b>Planning</b>${T.sarah.assignment} · due ${T.sarah.due}</div></div><h3>Recent evidence</h3><div class="evidence"><div><b>Concept understanding</b>Strong</div><div><b>Independent application</b>Developing</div><div><b>Tutor context</b>Guided support completed</div><div><b>Habit context</b>${T.sarah.streak}-day consistent study streak · ${T.sarah.reviewCards} review cards today</div></div><h3>E Deviser interpretation</h3><p>A short Teacher check-in may help Sarah transfer the concept into independent application.</p><div class="teacher-governance"><b>Prepared by:</b> Mastery Agent · Tutor Agent · Intervention Agent<br><b>Evidence:</b> Checked · <b>Policy:</b> Teacher authorized</div><div class="flex gap-2 mt-4"><button class="btn3d sm" onclick="openSarahIntervention()">Review handoff</button><button class="btn3d sm b-ghost" onclick="location.href='teacher-student-detail.html'">Open evidence</button></div>`);
  window.openSarahIntervention=()=>drawer('Sarah Ahmed · Intervention review',`<h3>What changed</h3><div class="evidence"><div><b>Current mastery</b>62% · Developing</div><div><b>Tutor support</b>Guided help completed</div><div><b>Assignment</b>Due Friday</div></div><h3>Student handoff</h3><p>Sarah consented to share: current question, course, CLO context and relevant Tutor summary.</p><p>Not shared: unrelated conversations, private journal, or other course activity.</p><h3>E Deviser suggestion <span class="teacher-a2">AI assistance · A2</span></h3><p><b>5-minute Teacher check-in</b><br>“Show me where the transitive dependency appears and explain why your schema change removes it.”</p><div class="teacher-governance"><b>Expected outcome:</b> Sarah independently explains the normalization choice. This action is a draft and requires your approval.</div><div class="flex gap-2 mt-4"><button class="btn3d sm" onclick="approveSarahIntervention(this)">Approve intervention</button><button class="btn3d sm b-ghost" onclick="closeTeacherDrawer()">Keep as draft</button></div>`);
  window.closeTeacherDrawer=close;
  window.approveSarahIntervention=(button)=>{setState('approved');button.textContent='Approved · follow-up queued';button.disabled=true;button.style.opacity='.75';const note=document.createElement('p');note.className='text-xs text-green-700 mt-3 font-bold';note.textContent='Teacher-approved follow-up recorded. Remeasurement is pending after Assignment 3.';button.parentElement.after(note);};
  window.resetTeacherDemo=()=>{setState('pending');location.reload()};
  // Make generic “why” affordances on Sarah rows useful instead of black-box risk explanations.
  document.querySelectorAll('[data-sarah-evidence]').forEach(el=>el.addEventListener('click',window.openSarahEvidence));
  if(page==='teacher-handoffs'){
    const pending=document.querySelector('[data-ho="pending"]');if(pending&&!document.getElementById('sarah-handoff-card')){const card=document.createElement('div');card.id='sarah-handoff-card';card.className='ho-card';card.innerHTML=`<div class="flex items-center gap-3 mb-1"><div class="h-9 w-9 rounded-full bg-sky-500 flex items-center justify-center text-white text-sm font-bold">S</div><div class="flex-1"><p class="text-sm font-bold text-gray-900">Sarah Ahmed</p><p class="text-[11px] text-gray-400">CS301 · ${getState()}</p></div><span class="pill pill-amber">Consent confirmed</span></div><p class="text-xs text-gray-600">Guided support on Normalization is complete; independent application needs review before Assignment 3 on Friday.</p><div class="ho-suggest"><p class="text-[10px] font-black text-blue-700 uppercase tracking-wide mb-1">Teacher-safe suggestion</p><p class="text-xs text-blue-900">Prepare a five-minute check-in using Sarah’s consented course and CLO context.</p></div><div class="flex gap-2"><button class="btn3d sm" onclick="openSarahIntervention()">Review handoff</button><button class="btn3d sm b-ghost" onclick="openSarahEvidence()">Open evidence</button></div>`;pending.prepend(card)}}
})();
